/**
 * AI Roleplay conversation module - compiled
 * @package mod_airoleplay
 */
define("mod_airoleplay/conversation",["exports","core/ajax"],function(exports,Ajax){
"use strict";
Object.defineProperty(exports,"__esModule",{value:!0});

class ConversationController{
constructor(e){
this.sessionId=e.sessionId;this.sessionToken=e.sessionToken;
this.isProcessing=!1;this.sessionActive=!0;this.turnCount=0;
this.startTime=Date.now();this.maxTurns=e.maxTurns||0;
this.maxDuration=e.maxDuration||0;
this.personaName=e.persona&&e.persona.name?e.persona.name:"AI";
if(window.airConvConfig){
var c=window.airConvConfig;
this.sessionId=c.sessionId||this.sessionId;
this.sessionToken=c.sessionToken||this.sessionToken;
this.resultsUrl=c.resultsUrl||"";
this.personaName=c.personaName||this.personaName;
this.maxDuration=c.maxDuration||this.maxDuration;
this.maxTurns=c.maxTurns||this.maxTurns;
}
this._bindEvents();this._startTimer();this._scrollBottom();
}
_bindEvents(){
var t=this;
var sb=document.getElementById("air-send-btn");
sb&&sb.addEventListener("click",function(){t.sendMessage();});
var eb=document.getElementById("air-end-btn");
eb&&eb.addEventListener("click",function(){t.endSession();});
var inp=document.getElementById("air-message-input");
inp&&inp.addEventListener("keydown",function(e){
if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();t.sendMessage();}
});
inp&&inp.addEventListener("input",function(){
this.style.height="auto";
this.style.height=Math.min(this.scrollHeight,120)+"px";
});
window.addEventListener("beforeunload",function(e){
if(t.sessionActive&&t.turnCount>0){e.preventDefault();e.returnValue="";}
});
}
async sendMessage(){
if(this.isProcessing||!this.sessionActive)return;
var inp=document.getElementById("air-message-input");
var text=inp?inp.value.trim():"";
if(!text)return;
inp.value="";inp.style.height="auto";
this._setProcessing(!0);this._appendMsg("user",text);
this.turnCount++;
var tc=document.getElementById("air-turn-count");
tc&&(tc.textContent=this.turnCount);
this._showTyping();
try{
var result=await Ajax.call([{methodname:"mod_airoleplay_send_message",args:{session_id:this.sessionId,session_token:this.sessionToken,message:text}}])[0];
this._hideTyping();
if(result&&result.ai_response)this._appendMsg("ai",result.ai_response);
this._updateSentiment(result?result.sentiment:"neutral",result?result.sentiment_score:0.5);
if(result&&result.should_end){await new Promise(r=>setTimeout(r,1500));await this.endSession();}
}catch(e){
this._hideTyping();
this._appendSys("Error: "+(e&&e.message?e.message:"Check API key in admin settings."),"error");
}finally{this._setProcessing(!1);}
}
async endSession(){
if(!this.sessionActive)return;
this.sessionActive=!1;
this._appendSys("Ending session...","info");
try{await Ajax.call([{methodname:"mod_airoleplay_end_session",args:{session_id:this.sessionId,session_token:this.sessionToken}}])[0];}catch(e){}
var url=this.resultsUrl||(M.cfg.wwwroot+"/mod/airoleplay/results.php?session="+this.sessionId);
window.location.href=url;
}
_appendMsg(role,content){
var container=document.getElementById("air-chat-messages");
if(!container)return;
var tw=document.getElementById("air-typing-wrapper");
var wrap=document.createElement("div");
wrap.className="air-msg "+(role==="user"?"air-msg-user":"air-msg-ai");
var avt=document.createElement("div");
avt.className="air-msg-avatar "+(role==="user"?"air-msg-avatar-user":"air-msg-avatar-ai");
avt.textContent=role==="user"?"You":this.personaName.charAt(0);
var bub=document.createElement("div");
bub.className="air-bubble "+(role==="user"?"air-bubble-user":"air-bubble-ai");
bub.innerHTML=this._esc(content).replace(/\n/g,"<br>");
wrap.appendChild(avt);wrap.appendChild(bub);
tw?container.insertBefore(wrap,tw):container.appendChild(wrap);
this._scrollBottom();
}
_appendSys(text,type){
var c=document.getElementById("air-chat-messages");if(!c)return;
var el=document.createElement("div");
el.style.cssText="text-align:center;font-size:12px;padding:5px 14px;border-radius:999px;width:fit-content;margin:0 auto;";
el.style.background=type==="error"?"#fee2e2":"#eff6ff";
el.style.color=type==="error"?"#991b1b":"#1d4ed8";
el.textContent=text;c.appendChild(el);this._scrollBottom();
if(type!=="error")setTimeout(function(){el.parentNode&&el.parentNode.removeChild(el);},4000);
}
_showTyping(){var w=document.getElementById("air-typing-wrapper");w&&(w.style.display="flex");this._scrollBottom();}
_hideTyping(){var w=document.getElementById("air-typing-wrapper");w&&(w.style.display="none");}
_setProcessing(s){
this.isProcessing=s;
var b=document.getElementById("air-send-btn"),i=document.getElementById("air-message-input");
b&&(b.disabled=s);i&&(i.disabled=s);
var t=b&&b.querySelector(".air-btn-text"),sp=b&&b.querySelector(".air-btn-spinner");
t&&(t.style.display=s?"none":"");sp&&(sp.style.display=s?"":"none");
}
_updateSentiment(s,score){
var el=document.getElementById("air-sentiment-indicator");
if(el)el.textContent=s==="positive"?"😊":s==="negative"?"😟":"😐";
var bar=document.getElementById("air-confidence-meter");
if(bar){bar.style.width=Math.round((score||0.5)*100)+"%";bar.style.background=s==="positive"?"#22c55e":s==="negative"?"#ef4444":"#6366f1";}
}
_startTimer(){
var el=document.getElementById("air-timer");if(!el)return;
var t=this;
this._timerInterval=setInterval(function(){
var e=Math.floor((Date.now()-t.startTime)/1000);
el.textContent=String(Math.floor(e/60)).padStart(2,"0")+":"+String(e%60).padStart(2,"0");
if(t.maxDuration&&e>=t.maxDuration-30)el.style.color="#ef4444";
if(t.maxDuration&&e>=t.maxDuration&&t.sessionActive){
t._appendSys("Time is up!","info");setTimeout(function(){t.endSession();},2000);
}
},1000);
}
_scrollBottom(){
var c=document.getElementById("air-chat-messages");
c&&setTimeout(function(){c.scrollTo({top:c.scrollHeight,behavior:"smooth"});},50);
}
_esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
}

class ResultsController{
constructor(e){this.sessionId=e.sessionId;}
}

const init=(config)=>{
if(!config)return;
if(config.page==="conversation")return new ConversationController(config);
if(config.page==="results")return new ResultsController(config);
};

exports.init=init;exports["default"]={init};
});
